from collections import deque

class Solution:
    def findCheapestPrice(self, n: int, flights: list[list[int]], src: int, dst: int, k: int) -> int:
        adj_list = [[] for _ in range(n)]
        price_taken = [float("inf") for _ in range(n)]
        for u, v, c in flights:
            adj_list[u].append((v, c))

        price_taken[src] = 0
        # no PQ — stops increase uniformly by +1 each hop
        q = deque()
        q.append((src, 0, 0))  # city, stop_count, price

        while q:
            u, stop_count, price = q.popleft()
            if stop_count == k + 1:
                continue

            for v, dp in adj_list[u]:
                np = dp + price
                if np < price_taken[v]:
                    price_taken[v] = np
                    q.append((v, stop_count + 1, np))

        return -1 if price_taken[dst] == float("inf") else price_taken[dst]

class Solution:
    def findCheapestPrice(self, n: int, flights: list[list[int]], src: int, dst: int, k: int) -> int:
        dist = [float("inf")] * n
        dist[src] = 0

        for _ in range(k + 1):
            temp = dist[:]
            for u, v, w in flights:
                if dist[u] != float("inf") and dist[u] + w < temp[v]:
                    temp[v] = dist[u] + w
            dist = temp

        return -1 if dist[dst] == float("inf") else dist[dst]

